import java.io.*;
import java.text.DecimalFormat;
import java.util.*;
import java.util.stream.IntStream;

public class c_v3 {

    public static void main(String[] args) {
        FS in = new FS(System.in);
        int n = in.nextInt();
        Circle[] circles = new Circle[n];
        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(new Vec(in.nextInt(), in.nextInt()), in.nextInt());
        }

        List<Vec> allPoints = new ArrayList<>();
        int[] parent = IntStream.range(0, n).toArray();
        int result = 1;

        for (int i = 0; i < n; i++) {
            List<Vec> currentPoints = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                Vec[] pts = circles[i].intersect(circles[j]);
                if (pts == null) continue;

                int rootI = find(parent, i);
                int rootJ = find(parent, j);
                parent[rootI] = rootJ;

                for (Vec p : pts) {
                    boolean duplicate = false;
                    for (Vec q : currentPoints) {
                        if (p.equals(q)) {
                            duplicate = true;
                            break;
                        }
                    }
                    if (!duplicate) currentPoints.add(p);
                }
            }

            result += currentPoints.size();

            for (Vec p : currentPoints) {
                boolean duplicate = false;
                for (Vec q : allPoints) {
                    if (p.equals(q)) {
                        duplicate = true;
                        break;
                    }
                }
                if (!duplicate) allPoints.add(p);
            }
        }

        result -= allPoints.size();
        int components = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == i) components++;
        }
        result += components;

        System.out.println(result);
    }

    private static int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    static class Circle {
        Vec center;
        double radius;

        public Circle(Vec center, double radius) {
            this.center = center;
            this.radius = radius;
        }

        public boolean contains(Vec v) {
            return center.sub(v).mag2() - Vec.EPS * Vec.EPS <= radius * radius;
        }

        public Vec[] intersect(Circle other) {
            if (center.equals(other.center)) return null;
            Vec direction = other.center.sub(center);
            double distSq = direction.mag2();
            double dist = Math.sqrt(distSq);

            if (radius + other.radius < dist || radius + dist < other.radius || other.radius + dist < radius) {
                return null;
            }

            if (Vec.eq(radius + other.radius, dist) || Vec.eq(other.radius + dist, radius)) {
                return new Vec[]{center.add(direction.scale(radius / dist))};
            }
            if (Vec.eq(radius + dist, other.radius)) {
                return new Vec[]{center.sub(direction.scale(radius / dist))};
            }

            double d1 = (radius * radius + distSq - other.radius * other.radius) / (2 * dist);
            double h = Math.sqrt(radius * radius - d1 * d1);
            Vec unitDir = direction.unit();
            Vec rightInt = center.add(unitDir.scale(d1).add(unitDir.rot270().scale(h)));
            Vec leftInt = center.add(unitDir.scale(d1).add(unitDir.rot90().scale(h)));
            return new Vec[]{rightInt, leftInt};
        }
    }

    static class Vec {
        static final double EPS = 1e-9;
        double x, y;

        public Vec(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vec add(Vec o) { return new Vec(x + o.x, y + o.y); }
        public Vec sub(Vec o) { return new Vec(x - o.x, y - o.y); }
        public Vec scale(double s) { return new Vec(x * s, y * s); }
        public double dot(Vec o) { return x * o.x + y * o.y; }
        public double cross(Vec o) { return x * o.y - y * o.x; }
        public double mag2() { return dot(this); }
        public double mag() { return Math.sqrt(mag2()); }
        public Vec unit() { return scale(1 / mag()); }
        public Vec rot90() { return new Vec(-y, x); }
        public Vec rot270() { return new Vec(y, -x); }

        public Vec rotate(double theta) {
            double newX = x * Math.cos(theta) + y * Math.cos(Math.PI / 2 + theta);
            double newY = x * Math.sin(theta) + y * Math.sin(Math.PI / 2 + theta);
            return new Vec(newX, newY);
        }

        public double angle() {
            return (Math.atan2(y, x) + 2 * Math.PI) % (2 * Math.PI);
        }

        public String toString() {
            DecimalFormat df = new DecimalFormat("#.##");
            return "(" + df.format(x) + ", " + df.format(y) + ")";
        }

        static boolean eq(double a, double b) { return Math.abs(a - b) < EPS; }
        static boolean leq(double a, double b) { return a - EPS < b; }
        static boolean geq(double a, double b) { return a + EPS > b; }

        public boolean equals(Object o) {
            Vec other = (Vec) o;
            return eq(x, other.x) && eq(y, other.y);
        }
    }

    static class FS {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FS(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    return next();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
